const SHELL_CACHE='spotlight-shell-v3',AUDIO_CACHE='spotlight-audio-v1';
const SHELL=['./','./index.html','./styles.css','./mobile.css','./app.js','./core.mjs','./offline.js','./data.json','./audio-manifest.json','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(SHELL_CACHE);await cache.addAll(SHELL);await self.skipWaiting();})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const name of await caches.keys())if(name.startsWith('spotlight-shell-')&&name!==SHELL_CACHE)await caches.delete(name);await self.clients.claim();})()));
function rangeResponse(response,range){return (async()=>{const data=await response.arrayBuffer();const match=/^bytes=(\d*)-(\d*)$/.exec(range);if(!match||(!match[1]&&!match[2]))return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+data.byteLength}});let start=match[1]?Number(match[1]):Math.max(0,data.byteLength-Number(match[2]));let end=match[1]?(match[2]?Math.min(Number(match[2]),data.byteLength-1):data.byteLength-1):data.byteLength-1;if(start>end||start>=data.byteLength)return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+data.byteLength}});return new Response(data.slice(start,end+1),{status:206,headers:{'Content-Type':'audio/wav','Content-Length':String(end-start+1),'Content-Range':'bytes '+start+'-'+end+'/'+data.byteLength,'Accept-Ranges':'bytes'}});})();}
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin)return;if(url.pathname.includes('/audio/')){event.respondWith((async()=>{const cache=await caches.open(AUDIO_CACHE);const cached=await cache.match(url.href);if(cached)return request.headers.has('range')?rangeResponse(cached,request.headers.get('range')):cached;return fetch(request);})());return;}event.respondWith((async()=>{const cache=await caches.open(SHELL_CACHE);const cached=await cache.match(request,{ignoreSearch:true});if(cached)return cached;try{return await fetch(request);}catch(error){if(request.mode==='navigate')return (await cache.match(new URL('./index.html',self.registration.scope).href))||Response.error();throw error;}})());});
